with.script:
const { owner, repo } = context.repo;
const milestoneTitle = 'Next Release';

const pulls = await github.paginate(github.rest.repos.listPullRequestsAssociatedWithCommit, {
  owner,
  repo,
  commit_sha: context.sha,
  per_page: 100,
});

const pull = pulls.find(({ merged_at, base }) => merged_at && base.ref === 'main');

if (!pull) {
  core.info(`No merged pull request found for ${context.sha}.`);
  return;
}

const milestones = await github.paginate(github.rest.issues.listMilestones, {
  owner,
  repo,
  state: 'open',
  per_page: 100,
});

let milestone = milestones.find(({ title }) => title === milestoneTitle);

if (!milestone) {
  const response = await github.rest.issues.createMilestone({
    owner,
    repo,
    title: milestoneTitle,
  });

  milestone = response.data;
}

await github.rest.issues.update({
  owner,
  repo,
  issue_number: pull.number,
  milestone: milestone.number,
});

core.info(`Assigned ${milestoneTitle} milestone to pull request #${pull.number}.`);

const fs = require('fs');
const { getChangedPackagesSinceRef } = require('@changesets/git');

try {
  const cwd = process.cwd();
  const baseRef = `origin/${process.env.BASE_REF}`;

  // 1. Get packages that actually changed in this PR/branch
  core.info(`🔍 Detecting changed packages since ${baseRef}...`);
  const changedPackages = await getChangedPackagesSinceRef({
    cwd,
    ref: baseRef
  });

  // 2. Filter out private packages
  const publicChangedPackages = changedPackages.filter(pkg => {
    const isPrivate = pkg.packageJson.private === true;
    if (isPrivate) {
      core.info(`🔒 Skipping private package: ${pkg.packageJson.name}`);
    }
    return !isPrivate;
  });

  const publicChangedPackageNames = publicChangedPackages.map(pkg => pkg.packageJson.name);
  core.info(`📦 Public changed packages: ${JSON.stringify(publicChangedPackageNames)}`);

  // 3. Parse changeset files added in this PR
  const changesetFiles = `${{ steps.cs.outputs.changeset_added_files }}`.split(',').filter(f => f);
  core.info(`📝 Added changeset files: ${JSON.stringify(changesetFiles)}`);

  const packagesInChangesets = new Set();

  for (const file of changesetFiles) {
    if (!fs.existsSync(file)) {
      core.warning(`⚠️ Changeset file not found: ${file}`);
      continue;
    }

    const content = fs.readFileSync(file, 'utf8');
    const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);

    if (frontmatterMatch) {
      const frontmatter = frontmatterMatch[1];
      // Parse YAML frontmatter to extract package names
      const packageLines = frontmatter.split('\n').filter(line => 
        line.trim() && !line.startsWith('#') && line.includes(':')
      );

      packageLines.forEach(line => {
        // Match valid npm package names (scoped or unscoped)
        // Scoped: @scope/package-name, Unscoped: package-name
        const packageMatch = line.match(/["']?(@[a-z0-9-_.]+\/[a-z0-9-_.]+|[a-z0-9-_.]+)["']?\s*:/i);
        if (packageMatch) {
          packagesInChangesets.add(packageMatch[1].trim());
        }
      });
    }
  }

  core.info(`📋 Packages covered by changesets: ${JSON.stringify(Array.from(packagesInChangesets))}`);

  // 4. Compare: find public packages that changed but aren't in changesets
  const uncoveredPackages = publicChangedPackageNames.filter(pkg => 
    !packagesInChangesets.has(pkg)
  );

  if (uncoveredPackages.length > 0) {
    const errorMessage = [
      '❌ The following public packages are changed but NOT covered by changesets:',
      ...uncoveredPackages.map(pkg => `  - ${pkg}`),
      '',
      '💡 Please add these packages to your changeset or create additional changesets'
    ].join('\n');

    core.setFailed(errorMessage);
    return;
  }

  // 5. Also check for packages in changesets that didn't actually change (optional warning)
  const extraPackages = Array.from(packagesInChangesets).filter(pkg =>
    !publicChangedPackageNames.includes(pkg)
  );

  if (extraPackages.length > 0) {
    const warningMessage = [
      '⚠️ The following packages are in changesets but have no changes:',
      ...extraPackages.map(pkg => `  - ${pkg}`),
      'This is usually okay for dependency bumps or cross-package updates'
    ].join('\n');

    core.warning(warningMessage);
  }

  core.info(publicChangedPackageNames.length === 0 
    ? '✅ No public packages changed - validation passed'
    : '✅ All public changed packages are covered by changesets!'
  );

} catch (error) {
  core.setFailed(`❌ Error validating changeset coverage: ${error.message}\n${error.stack}`);
}

// workflow_run.pull_requests is empty for fork PRs, so resolve the pull
// request from the head branch instead of trusting anything the fork sends
const run = context.payload.workflow_run;

// Null when the fork is deleted or made private between the check run and this event
const headOwner = run.head_repository?.owner?.login;

if (!headOwner) {
  core.info('No head repository on the run, skipping');
  return;
}

const prs = await github.rest.pulls.list({
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open',
  head: `${headOwner}:${run.head_branch}`,
  per_page: 100,
});

const pr = prs.data.find((pr) => pr.head.sha === run.head_sha);

if (!pr) {
  core.info('No open pull request points at this commit, skipping');
  return;
}

core.setOutput('number', pr.number);
core.setOutput('draft', String(pr.draft));

const { readFileSync } = require('node:fs');

// Fork-controlled content reaching a write-scoped job: only use it when it
// is exactly the list of mentions the CLA bot is meant to hand over
const handoff = readFileSync('cla-missing/missing', 'utf8').trim();
const isMentionList = /^@[\w-]{1,39}(, @[\w-]{1,39})*$/.test(handoff);

if (!isMentionList) core.warning('Unexpected CLA handoff contents, falling back to a generic greeting');

core.setOutput('mentions', isMentionList ? handoff : 'there');

await github.rest.issues.addLabels({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: Number(process.env.PR_NUMBER),
  labels: [process.env.CLA_LABEL],
});

try {
  await github.rest.issues.removeLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: Number(process.env.PR_NUMBER),
    name: process.env.CLA_LABEL,
  });
} catch (error) {
  if (error.status !== 404) throw error;
}

const TWO_WEEKS_MS = 14 * 24 * 60 * 60 * 1000;
const LABEL_NAME = 'Changes Requested';
const now = new Date();

const prs = await github.paginate(github.rest.pulls.list, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open',
  per_page: 100,
});

for (const pr of prs) {
  const hasLabel = pr.labels.some(l => l.name === LABEL_NAME);
  if (!hasLabel) continue;

  const events = await github.paginate(github.rest.issues.listEventsForTimeline, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: pr.number,
    per_page: 100,
  });

  // Find the most recent time this label was applied
  const labelEvents = events
    .filter(e => e.event === 'labeled' && e.label?.name === LABEL_NAME)
    .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

  if (labelEvents.length === 0) continue;

  const labeledAt = new Date(labelEvents[0].created_at);
  if (now - labeledAt < TWO_WEEKS_MS) continue;

  // Check if the PR author pushed new commits after the label was applied
  const commits = await github.paginate(github.rest.pulls.listCommits, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: pr.number,
    per_page: 100,
  });

  const pushedAfterLabel = commits.some(c => {
    const committedAt = new Date(c.commit.committer?.date ?? c.commit.author?.date);
    return c.author?.login === pr.user.login && committedAt > labeledAt;
  });

  if (pushedAfterLabel) {
    await github.rest.issues.removeLabel({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: pr.number,
      name: LABEL_NAME,
    });

    core.info(`Removed label from PR #${pr.number} — author pushed changes after review: ${pr.title}`);
    continue;
  }

  await github.rest.pulls.update({
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: pr.number,
    state: 'closed',
  });

  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: pr.number,
    body: "Hi there! 👋 This PR has requested changes but hasn't been updated in two weeks, so we're going to close it out. Our small team has limited resources so we need to remove noise periodically to keep our work focused. If you would like to continue to work on this, feel free to re-open this PR or submit a new one once the requested changes have been addressed. Thank you for contributing to Directus!🐰",
  });

  core.info(`Closed PR #${pr.number}: ${pr.title}`);
}

const discussionId = context.payload.discussion.node_id;

// Add comment first
await github.graphql(`
  mutation($discussionId: ID!, $body: String!) {
    addDiscussionComment(input: {discussionId: $discussionId, body: $body}) {
      comment {
        id
      }
    }
  }
`, {
  discussionId: discussionId,
  body: 'This discussion has been automatically closed. Please submit feature requests at https://roadmap.directus.com'
});

// Close the discussion
await github.graphql(`
  mutation($discussionId: ID!) {
    closeDiscussion(input: {discussionId: $discussionId}) {
      discussion {
        id
      }
    }
  }
`, {
  discussionId: discussionId
});

const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
const LABEL_NAME = process.env.CLA_LABEL;
const DOCS_URL = 'https://directus.com/docs/community/contribution/pull-requests#copyright-license-agreement-cla';
const dryRun = process.env.DRY_RUN === 'true';
const now = new Date();

const prs = await github.paginate(github.rest.pulls.list, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open',
  per_page: 100,
});

for (const pr of prs) {
  try {
    if (pr.draft) continue;
    if (!pr.labels.some((label) => label.name === LABEL_NAME)) continue;

    const events = await github.paginate(github.rest.issues.listEventsForTimeline, {
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: pr.number,
      per_page: 100,
    });

    // Find the most recent time this label was applied
    const [labeledAt] = events
      .filter((event) => event.event === 'labeled' && event.label?.name === LABEL_NAME)
      .map((event) => new Date(event.created_at))
      .sort((a, b) => b - a);

    if (!labeledAt || now - labeledAt < ONE_WEEK_MS) continue;

    // The label only refreshes when the PR is pushed to, so confirm against
    // the CLA check for the commit the PR currently points at
    const runs = await github.rest.actions.listWorkflowRuns({
      owner: context.repo.owner,
      repo: context.repo.repo,
      workflow_id: 'cla.yml',
      head_sha: pr.head.sha,
      per_page: 100,
    });

    const [latestRun] = runs.data.workflow_runs
      .filter((run) => run.status === 'completed')
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

    if (!latestRun) {
      core.warning(`Skipped PR #${pr.number} — no completed CLA check for ${pr.head.sha}`);
      continue;
    }

    if (latestRun.conclusion === 'success') {
      if (!dryRun) {
        await github.rest.issues.removeLabel({
          owner: context.repo.owner,
          repo: context.repo.repo,
          issue_number: pr.number,
          name: LABEL_NAME,
        });
      }

      core.info(`${dryRun ? 'Would remove' : 'Removed'} label from PR #${pr.number} — the CLA has since been signed: ${pr.title}`);
      continue;
    }

    if (dryRun) {
      core.info(`Would close PR #${pr.number}: ${pr.title}`);
      continue;
    }

    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: pr.number,
      body: `Hi @${pr.user.login}! 👋 We're closing this PR because the Contributor License Agreement (CLA) hasn't been signed in the past week. We can't consider a contribution until every contributor on it has signed. To sign it, add the missing GitHub username(s) to \`contributors.yml\` — see [our contribution docs](${DOCS_URL}) for details. Feel free to reopen this PR once that's done. Thank you for contributing to Directus! 🐰`,
    });

    await github.rest.pulls.update({
      owner: context.repo.owner,
      repo: context.repo.repo,
      pull_number: pr.number,
      state: 'closed',
    });

    core.info(`Closed PR #${pr.number}: ${pr.title}`);
  } catch (error) {
    core.warning(`Failed to process PR #${pr.number}: ${error.message}`);
  }
}

